@startuml
class Match {
  -date : LocalDateTime
  -name : String
  -players : Player
  +winner : Result
  play()
  -generateMatchInformation()
  -calculateResult() : Result
}
class Player {
  -name : String
  -totalScore : Integer
  -games : Game
}
class Game {
  -number : Integer
  -score : Integer
  calculateScore()
}
class Attempt {
  number : Integer
  points : Integer
}
enum ScoreType {
  STRIKE
  SPARE
  NONE
}
class FileImporter {
  -INITIAL_DATAFILE : String
  loadData() : List_InitialData
}
class InitialData {
  -playerName : String
  -points
}
class Result {
  +player : Player
  +score : Integer
}
interface Importer {
  loadData() : List_InitialData
}
class BowlingGame {
  +attempts : List_Attempt
  scoreType : ScoreType
  previousGame : Game
  nextGames : List_Game
}
Importer <|.. FileImporter
Game <|-- BowlingGame
@enduml

@startuml
class PaypalProcessor {
  process()
}
class SetExpressCheckoutProcessor {
  getPaypalRequest()
  getPaypalResponse()
  process()
}
class GetExpressCheckoutDetailsProcessor {
  getPaypalRequest()
  getPaypalResponse()
  process()
}
class DoExpressCheckoutDetailsProcessor {
  getPaypalRequest()
  getPaypalResponse()
  process()
}
interface IPaypalProcessor {
  getPaypalRequest()
  getPaypalResponse()
  process()
}
class SetExpressCheckoutAdapter
class GetExpressCheckoutDetailsAdapter
class DoExpressCheckoutDetailsAdapter
IPaypalProcessor <|.. SetExpressCheckoutProcessor
IPaypalProcessor <|.. GetExpressCheckoutDetailsProcessor
IPaypalProcessor <|.. DoExpressCheckoutDetailsProcessor
PaypalProcessor ..> IPaypalProcessor
SetExpressCheckoutProcessor ..> SetExpressCheckoutAdapter
GetExpressCheckoutDetailsProcessor ..> GetExpressCheckoutDetailsAdapter
DoExpressCheckoutDetailsProcessor ..> DoExpressCheckoutDetailsAdapter
@enduml

@startuml
class OrdenesPedidos {
  -codigo : String
  -fecha : String
}
class Proveedor {
  -nit : String
  -nombre : String
  -direccion : String
  -telefono : String
}
class Factura {
  -codigo : String
  -fecha : String
}
class Elementos {
  -referencia : String
  -clasificacion : String
}
class SolicitudSuministros {
  -codigo : String
  -fecha : String
}
class dependencia {
  -codigo : String
  -nombre : String
  -responsable : String
}
class Pedidos {
  -codigo : String
  -fecha : String
}
Proveedor "1" -- "0..*" OrdenesPedidos : es enviado
Pedidos "0..*" -- "1" Proveedor : provee
OrdenesPedidos "0..*" -- "1..*" Elementos : conforma
SolicitudSuministros "0..*" -- "1..*" Elementos : relaciona
SolicitudSuministros "1..*" -- "0..1" OrdenesPedidos : genera
dependencia "1" -- "1..*" SolicitudSuministros : realiza
Factura "0..*" -- "1" Proveedor : elabora
Factura "0..*" -- "1..*" Elementos : factura
@enduml

@startuml
class Airline {
  id : String
}
class Flight {
  id : Integer
  departureTime : Date
  arrivalTime : Date
}
class Airport {
  id : String
}
class Pilot
class Aircraft {
  state : MaintenanceState
  flightState : FlightState
}
enum MaintenanceState {
  Working
  UnderRepair
}
enum FlightState {
  Landed
  Airborne
}
class Company
class CoPilot
class Navigator
class Captain
Pilot <|-- CoPilot
Pilot <|-- Navigator
Pilot <|-- Captain
Airline "0..*" *-- "0..*" Aircraft : Airline_Aircraft
Company "1" *-- "1..*" Pilot : Company_Pilot
Flight "0..*" *-- "1" Airport : Flights_Airport
Flight "0..*" *-- "1" Airport : Flights_Airport2
Airline "1" *-- "0..*" Flight : Airline_Flight
Flight "0..*" *-- "1" Aircraft : Flight_Aircraft
Aircraft "0..*" *-- "0..*" Pilot : Aircraft_Pilot
Aircraft "0..*" *-- "1..*" CoPilot : Aircraft_CoPilot
Aircraft "0..*" *-- "1..*" Captain : Aircraft_Captain
@enduml

@startuml
class Airline {
  id : String
}
class Flight {
  id : Integer
  departureTime : Date
  arrivalTime : Date
}
class Airport {
  id : String
}
class Pilot
class Aircraft {
  state : MaintenanceState
  flightState : FlightState
}
enum MaintenanceState {
  Working
  UnderRepair
}
enum FlightState {
  Landed
  Airborne
}
class Company
class CoPilot
class Navigator
class Captain
Pilot <|-- Captain
Aircraft "0..*" *-- "1..*" Captain : Aircraft_Captain
Flight "0..*" *-- "1" Aircraft : Flight_Aircraft
Pilot <|-- CoPilot
Company "1" *-- "1..*" Pilot : Company_Pilot
Flight "0..*" *-- "1" Airport : Flights_Airport2
Pilot <|-- Navigator
Aircraft "0..*" *-- "1..*" CoPilot : Aircraft_CoPilot
Flight "0..*" *-- "1" Airport : Flights_Airport
Aircraft "0..*" *-- "0..*" Pilot : Aircraft_Pilot
Airline "1" *-- "0..*" Flight : Airline_Flight
Airline "0..*" *-- "0..*" Aircraft : Airline_Aircraft
@enduml

@startuml
class elevator {
  floor : Integer
}
class door {
  close : Boolean
}
class button {
  number : Integer
}
class elevator_s_buttons {
  number : Integer
}
class floor_s_buttons {
  number : Boolean
}
button <|-- elevator_s_buttons
button <|-- floor_s_buttons
door "1" -- "1" elevator : elevator_door
button "0..*" -- "0..1" elevator : elevator_button
@enduml
